def split_fields(text: str) -> list[str]:
    fields = []
    field = ""
    escaped = False
    for index in range(len(text)):
        character = text[index]
        if escaped:
            if character == "," or character == "\\":
                field = field + character
                escaped = False
            else:
                raise ValueError("invalid escape")
        elif character == "\\":
            escaped = True
        elif character == ",":
            fields.append(field)
            field = ""
        else:
            field = field + character
    if escaped:
        raise ValueError("dangling escape")
    fields.append(field)
    return fields

